Ajv JSON schema validator — Getting started
Try it in the Node.js REPL:  https://runkit.com/npm/ajv
In JavaScript:
// or ESM/TypeScript import
import Ajv from "ajv"
// Node.js require:
const Ajv = require("ajv")

const ajv = new Ajv() // options can be passed, e.g. {allErrors: true}

const schema = {
  type: "object",
  properties: {
    foo: {type: "integer"},
    bar: {type: "string"},
  },
  required: ["foo"],
  additionalProperties: false,
}

const data = {
  foo: 1,
  bar: "abc",
}

const validate = ajv.compile(schema)
const valid = validate(data)
if (!valid) console.log(validate.errors)
Learn how to use Ajv and see more examples in the  Guide: getting started

body-parser — Examples — Express/Connect top-level generic
This example demonstrates adding a generic JSON and URL-encoded parser as a
top-level middleware, which will parse the bodies of all incoming requests.
This is the simplest setup.
const express = require('express')
const bodyParser = require('body-parser')

const app = express()

// parse application/x-www-form-urlencoded
app.use(bodyParser.urlencoded())

// parse application/json
app.use(bodyParser.json())

app.use(function (req, res) {
  res.setHeader('Content-Type', 'text/plain')
  res.write('you posted:\n')
  res.end(String(JSON.stringify(req.body, null, 2)))
})

body-parser — Examples — Express route-specific
This example demonstrates adding body parsers specifically to the routes that
need them. In general, this is the most recommended way to use body-parser with
Express.
const express = require('express')
const bodyParser = require('body-parser')

const app = express()

// create application/json parser
const jsonParser = bodyParser.json()

// create application/x-www-form-urlencoded parser
const urlencodedParser = bodyParser.urlencoded()

// POST /login gets urlencoded bodies
app.post('/login', urlencodedParser, function (req, res) {
  if (!req.body || !req.body.username) res.sendStatus(400)
  res.send('welcome, ' + req.body.username)
})

// POST /api/users gets JSON bodies
app.post('/api/users', jsonParser, function (req, res) {
  if (!req.body) res.sendStatus(400)
  // create user in req.body
})

body-parser — Examples — Change accepted type for parsers
All the parsers accept a  type  option which allows you to change the
 Content-Type  that the middleware will parse.
const express = require('express')
const bodyParser = require('body-parser')

const app = express()

// parse various different custom JSON types as JSON
app.use(bodyParser.json({ type: 'application/*+json' }))

// parse some custom thing into a Buffer
app.use(bodyParser.raw({ type: 'application/vnd.custom-type' }))

// parse an HTML body into a string
app.use(bodyParser.text({ type: 'text/html' }))

Bytes utility — Usage — bytes(number｜string value, [options]): number｜string｜null
Default export function. Delegates to either  bytes.format  or  bytes.parse  based on the type of  value .
Arguments
Name Type Description value number ｜ string Number value to format or string value to parse options Object Conversion options for  format
Returns
Name Type Description results string ｜ number ｜ null Return null upon error. Numeric value in bytes, or string value otherwise.
Example
bytes(1024);
// output: '1KB'

bytes('1KB');
// output: 1024

Bytes utility — Usage — bytes.format(number value, [options]): string｜null
Format the given value in bytes into a string. If the value is negative, it is kept as such. If it is a float, it is
rounded.
Arguments
Name Type Description value number Value in bytes options Object Conversion options
Options
Property Type Description decimalPlaces number ｜ null Maximum number of decimal places to include in output. Default value to  2 . fixedDecimals boolean ｜ null Whether to always display the maximum number of decimal places. Default value to  false thousandsSeparator string ｜ null Example of values:  ' ' ,  ','  and  '.' ... Default value to  '' . unit string ｜ null The unit in which the result will be returned (B/KB/MB/GB/TB). Default value to  ''  (which means auto detect). unitSeparator string ｜ null Separator to use between number and unit. Default value to  '' .
Returns
Name Type Description results string ｜ null Return null upon error. String value otherwise.
Example
bytes.format(1024);
// output: '1KB'

bytes.format(1000);
// output: '1000B'

bytes.format(1000, {thousandsSeparator: ' '});
// output: '1 000B'

bytes.format(1024 * 1.7, {decimalPlaces: 0});
// output: '2KB'

bytes.format(1024, {unitSeparator: ' '});
// output: '1 KB'

Bytes utility — Usage — bytes.parse(string｜number value): number｜null
Parse the string value into an integer in bytes. If no unit is given, or  value 
is a number, it is assumed the value is in bytes.
Supported units and abbreviations are as follows and are case-insensitive:
b  for bytes kb  for kilobytes mb  for megabytes gb  for gigabytes tb  for terabytes pb  for petabytes
The units are in powers of two, not ten. This means 1kb = 1024b according to this parser.
Arguments
Name Type Description value string ｜ number String to parse, or number in bytes.
Returns
Name Type Description results number ｜ null Return null upon error. Value in bytes otherwise.
Example
bytes.parse('1KB');
// output: 1024

bytes.parse('1024');
// output: 1024

bytes.parse(1024);
// output: 1024

call-bind-apply-helpers  — Usage/Examples
const assert = require('assert');
const callBindBasic = require('call-bind-apply-helpers');

function f(a, b) {
	assert.equal(this, 1);
	assert.equal(a, 2);
	assert.equal(b, 3);
	assert.equal(arguments.length, 2);
}

const fBound = callBindBasic([f, 1]);

